  const gateStyle = (status: CapitalReadiness["gates"][number]["status"]) => status === "met" ? "bg-[#DCEBD7] text-[#274C20]" : status === "not_met" ? "bg-[#F9D9D3] text-[#8E2F20]" : "bg-[#FFF0BF] text-[#705500]";
